item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import {z} from "zod";
  4	
  5	/**
  6	 * Executor of the method `plan-meeting-brief` (v6, after the fifth independent review). Assembles
  7	 * the first deliverable only from objects in a usable state, each fact bound to the fingerprint of
  8	 * the object it cites; a conditioned, partial or open object names a gap instead of filling a block.
  9	 * Points for and against the thesis come from the stance each object declared on its facts. The
 10	 * page plan honours the number of pages asked, carries the audience's discriminator, and allows
 11	 * production only once the person confirmed that exact plan. Questions the base already answers
 12	 * are refused whatever the caller says; a question that changes nothing is not asked. A previous
 13	 * version yields a change note instead of a silent rewrite. A block is filled only with facts; a
 14	 * usable object without facts names a gap. A conditioned or open object is carried as an uncovered
 15	 * term so its finding is never silently dropped. A financial figure in a fact carries its unit.
 16	 * Without audience or form the deliverable still goes out and the page plan waits. Points for and
 17	 * against the thesis come from the stance any usable object declared, never from a list of kinds.
 18	 * Only cited objects count as used. A question is asked only after a declared search of the base
 19	 * that found no answer. A fact's unit cannot contradict the fact's own words nor the unit of the
 20	 * object it quotes; every fact names the field of the object it reproduces; a fact that asserts a
 21	 * legal event (a breach) is refused, since no object asserts one. A plan that cannot hold the pages
 22	 * asked emits the question inside the cap of three. Every gap, open questions included, is an
 23	 * uncovered term. When an object's content is given, its fingerprint is recomputed from that
 24	 * content and every fact's path must resolve inside it. This executor plans; the prose of the
 25	 * pages is a model step downstream, never produced here.
 26	 */
 27	const nonEmpty = z.string().trim().min(1);
 28	const identifier = z.string().regex(/^[a-z][a-z0-9_.-]*$/);
 29	const sha256 = z.string().regex(/^[a-f0-9]{64}$/);
 30	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 31	type Anchor = z.infer<typeof anchorSchema>;
 32	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 33	
 34	export const objectKinds = ["debt_ledger", "maturity_wall", "covenants", "reconciliation", "interest_schedule", "scenarios", "exit_costs", "before_after", "company_view", "performance"] as const;
 35	/** States that let an object fill a block; every other state names a gap. */
 36	const USABLE_STATES = new Set(["complete", "resolved", "closes", "declared", "compared", "diagnosed"]);
 37	
 38	export const approvedObjectSchema = z.object({
 39	  id: identifier,
 40	  kind: z.enum(objectKinds),
 41	  state: z.enum(["complete", "resolved", "closes", "declared", "compared", "diagnosed", "conditioned", "incomplete", "partial", "open_divergences", "identity_failed", "blocked"]),
 42	  fingerprint: sha256,
 43	  /** The object's own content, as the executor that produced it emitted it; when given, the fingerprint must be the hash of this content and every fact's path must resolve inside it. */
 44	  content: z.record(z.string(), z.unknown()).nullable().default(null),
 45	  /** The monetary unit the object's figures are stated in, when it has any; a fact quoting a figure must carry the same unit. */
 46	  unit: nonEmpty.nullable().default(null),
 47	  /** Facts the deliverable may cite; each one is bound to the object's fingerprint, names the field it reproduces and declares its stance on the thesis. */
 48	  headlines: z.array(z.object({text: nonEmpty, stance: z.enum(["for", "against", "neutral"]), objectFingerprint: sha256, /** Unit of any figure the text carries (R$ mil, x, %); required when the text carries a thousands-separated number. */ unit: nonEmpty.nullable().default(null), /** The field of the object the fact reproduces, so a fact can be audited against the object it is bound to. */ objectPath: nonEmpty}).strict()).max(12).default([]),
 49	}).strict();
 50	
 51	export const briefRequestSchema = z.object({
 52	  turn: z.number().int().positive(),
 53	  /** The person the material is for first; the others do not change the discriminator. */
 54	  /** Null when the person has not said who the material is for; the deliverable goes out and the plan waits. */
 55	  audience: z.object({primary: nonEmpty, others: z.array(nonEmpty).default([])}).strict().nullable(),
 56	  form: z.enum(["first_deliverable", "internal_briefing", "pitch_pages", "analysis_with_scenarios", "board_deck"]).nullable(),
 57	  pages: z.number().int().positive().nullable().default(null),
 58	  /** What the sponsor said, kept verbatim. */
 59	  sponsorInstruction: z.string().nullable().default(null),
 60	  /** What the instruction left undefined, declared by the caller; the deliverable names it instead of hiding it. */
 61	  undefinedAspects: z.array(z.enum(["thesis", "meeting_type", "format", "audience", "depth"])).default([]),
 62	  confirmedPlanId: z.string().nullable().default(null),
 63	}).strict();
 64	
 65	export const candidateQuestionSchema = z.object({
 66	  id: identifier,
 67	  text: nonEmpty,
 68	  /** Why the answer changes the material; a question without a real reason is not asked. */
 69	  changesTheWork: nonEmpty,
 70	  /** The declared search of the base: which documents were checked and what was found; a question without a search is not asked, and a found answer refuses it. */
 71	  coverage: z.object({searched: z.array(nonEmpty).min(1), answeredBy: anchorSchema.nullable(), answer: nonEmpty.nullable()}).strict().nullable().default(null),
 72	  /** How much the answer changes the material, from the coverage map: lower asks first. */
 73	  priority: z.number().int().nonnegative(),
 74	}).strict();
 75	
 76	export const previousVersionSchema = z.object({
 77	  outputFingerprint: sha256,
 78	  blocks: z.array(z.object({id: identifier, state: z.enum(["filled", "gap"]), objectIds: z.array(identifier)}).strict()),
 79	  objectFingerprints: z.record(identifier, sha256),
 80	}).strict();
 81	
 82	export const briefInputSchema = z.object({
 83	  caseId: nonEmpty,
 84	  request: briefRequestSchema,
 85	  objects: z.array(approvedObjectSchema),
 86	  candidateQuestions: z.array(candidateQuestionSchema).default([]),
 87	  previousVersion: previousVersionSchema.nullable().default(null),
 88	}).strict().superRefine((input, context) => {
 89	  const objectIds = new Set<string>();
 90	  input.objects.forEach((object, index) => {
 91	    if (objectIds.has(object.id)) context.addIssue({code: "custom", path: ["objects", index], message: `duplicate object ${object.id}`});
 92	    objectIds.add(object.id);
 93	    if (object.content !== null) {
 94	      const recomputed = createHash("sha256").update(stableStringify(object.content)).digest("hex");
 95	      if (recomputed !== object.fingerprint) context.addIssue({code: "custom", path: ["objects", index, "fingerprint"], message: `${object.id}: the fingerprint is not the hash of the object's content; the content or the fingerprint was altered`});
 96	      if (object.unit !== null && typeof object.content.unit === "string" && object.content.unit !== object.unit) context.addIssue({code: "custom", path: ["objects", index, "unit"], message: `${object.id}: the declared unit ${object.unit} differs from the unit inside the object's content (${object.content.unit})`});
 97	    }
 98	    object.headlines.forEach((headline, position) => {
 99	      if (headline.objectFingerprint !== object.fingerprint) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the headline is bound to another fingerprint than the object's`});
100	      if (headline.unit === null && /\d{1,3}(\.\d{3})+/.test(headline.text)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: a fact with a figure needs its unit`});
101	      if (/rompid|rompiment|violad|violac|breach|descumpr|inadimpl|default declar|vencimento antecipado declar|acelerad/i.test(headline.text)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: a fact asserts a breach, a violation or a declared default; no object asserts a legal event, only an interim reading against a limit`});
102	      if (object.content !== null && resolvePath(object.content, headline.objectPath) === undefined) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the path ${headline.objectPath} does not resolve inside the object's content`});
103	      if (headline.unit !== null && object.unit !== null && /\d{1,3}(\.\d{3})+/.test(headline.text) && headline.unit.toLowerCase() !== object.unit.toLowerCase()) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the fact quotes a figure in ${headline.unit} and the object states its figures in ${object.unit}`});
104	      if (headline.unit !== null) {
105	        const words = headline.text.toLowerCase();
106	        const unit = headline.unit.toLowerCase();
107	        const saysThousand = /\bmil\b|thousand/.test(words) && !/milh/.test(words);
108	        const saysMillion = /milh[õo]es|million/.test(words);
109	        if (saysThousand && /milh|million/.test(unit)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the fact says thousands and its unit says millions`});
110	        if (saysMillion && /\bmil\b|thousand/.test(unit) && !/milh/.test(unit)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the fact says millions and its unit says thousands`});
111	      }
112	    });
113	  });
114	  const questionIds = new Set<string>();
115	  input.candidateQuestions.forEach((question, index) => {
116	    if (questionIds.has(question.id)) context.addIssue({code: "custom", path: ["candidateQuestions", index], message: `duplicate question ${question.id}`});
117	    questionIds.add(question.id);
118	    if (question.coverage && (question.coverage.answeredBy === null) !== (question.coverage.answer === null)) context.addIssue({code: "custom", path: ["candidateQuestions", index, "coverage"], message: `${question.id}: an answer and its anchor come together`});
119	  });
120	  const blockIds = new Set<string>();
121	  input.previousVersion?.blocks.forEach((block, index) => {
122	    if (blockIds.has(block.id)) context.addIssue({code: "custom", path: ["previousVersion", "blocks", index], message: `duplicate block ${block.id} in the previous version`});
123	    blockIds.add(block.id);
124	  });
125	  if (input.request.pages !== null && (input.request.form === "first_deliverable" || input.request.form === null)) context.addIssue({code: "custom", path: ["request", "pages"], message: "the first deliverable has no page plan; pages belong to a material form"});
126	});
127	export type BriefInput = z.input<typeof briefInputSchema>;
128	
129	type Kind = (typeof objectKinds)[number];
130	type Stance = "for" | "against" | "neutral";
131	const BLOCKS: Array<{id: string; label: string; needs: Kind[]; stance: Stance | null}> = [
132	  {id: "company_view", label: "Visão da companhia", needs: ["company_view"], stance: null},
133	  {id: "performance_outlook", label: "Desempenho histórico e outlook", needs: ["performance"], stance: null},
134	  {id: "debt_by_instrument", label: "Dívida por instrumento", needs: ["debt_ledger"], stance: null},
135	  {id: "maturity_schedule", label: "Cronograma de vencimentos", needs: ["maturity_wall"], stance: null},
136	  {id: "liquidity_coverage", label: "Liquidez e cobertura", needs: ["maturity_wall", "interest_schedule"], stance: null},
137	  {id: "assumptions", label: "Premissas preliminares", needs: ["scenarios"], stance: null},
138	  {id: "points_for_thesis", label: "Pontos que sustentam a tese", needs: [], stance: "for"},
139	  {id: "points_against_thesis", label: "Pontos contra a tese", needs: [], stance: "against"},
140	  {id: "initial_alternatives", label: "Alternativas iniciais", needs: ["before_after"], stance: null},
141	  {id: "open_questions", label: "Perguntas pendentes", needs: [], stance: null},
142	  {id: "exhibits", label: "Exhibits preliminares", needs: ["debt_ledger", "maturity_wall"], stance: null},
143	];
144	
145	const PAGE_PLANS: Record<"pitch_pages" | "internal_briefing" | "analysis_with_scenarios" | "board_deck", Array<{title: string; blocks: string[]}>> = {
146	  pitch_pages: [
147	    {title: "Situação atual", blocks: ["debt_by_instrument", "maturity_schedule", "liquidity_coverage", "points_against_thesis"]},
148	    {title: "Alternativas", blocks: ["initial_alternatives", "points_for_thesis"]},
149	    {title: "Impacto nos indicadores", blocks: ["assumptions", "exhibits"]},
150	  ],
151	  internal_briefing: [{title: "Briefing", blocks: ["company_view", "performance_outlook", "debt_by_instrument", "maturity_schedule", "points_for_thesis", "points_against_thesis", "open_questions"]}],
152	  analysis_with_scenarios: [{title: "Análise", blocks: ["debt_by_instrument", "maturity_schedule", "liquidity_coverage"]}, {title: "Cenários", blocks: ["assumptions", "initial_alternatives"]}],
153	  board_deck: [{title: "Contexto", blocks: ["company_view", "performance_outlook"]}, {title: "Estrutura de capital", blocks: ["debt_by_instrument", "maturity_schedule", "liquidity_coverage"]}, {title: "Alternativas e decisão", blocks: ["initial_alternatives", "points_for_thesis", "points_against_thesis"]}],
154	};
155	
156	type Block = {id: string; label: string; state: "filled" | "gap"; object_ids: string[]; pending_object_ids: string[]; headlines: Array<{text: string; unit: string | null; object_id: string; object_fingerprint: string; object_path: string | null}>; gap: string | null};
157	type Page = {number: number; title: string; blocks: string[]};
158	export type BriefOutput = {
159	  schema_version: "method.plan-meeting-brief.v6";
160	  case_id: string;
161	  turn: number;
162	  state: "planned" | "awaiting_confirmation";
163	  /** objects_used lists only the objects a filled block cites; usable objects without facts are listed apart. */
164	  deliverable: {blocks: Block[]; objects_used: string[]; objects_usable_not_cited: string[]; objects_pending: Array<{id: string; state: string}>; objects_excluded: Array<{id: string; state: string}>};
165	  page_plan: {state: "not_requested" | "awaiting_audience_and_form" | "proposed" | "confirmed" | "unsupported"; id: string | null; form: string | null; audience: {primary: string; others: string[]} | null; pages: Page[]; discriminator: string | null; production_allowed: boolean; reason: string | null};
166	  alignment_questions: Array<{id: string; text: string; changes_the_work: string}>;
167	  refused_questions: Array<{id: string; reason: string; answered_by: Anchor | null}>;
168	  /** What this executor does not produce: the prose of the pages is a model step downstream of the confirmed plan. */
169	  not_produced_here: string[];
170	  ambiguity_named: string | null;
171	  change_note: {previous_output_fingerprint: string; changes: string[]} | null;
172	  uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
173	  trace: {inputFingerprint: string; outputFingerprint: string};
174	};
175	
176	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
177	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
178	/** Resolves a dotted path with optional indexes ("coverage.by_period[0].coverage") inside an object; undefined when any step is missing. */
179	export function resolvePath(content: unknown, path: string): unknown {
180	  let current: unknown = content;
181	  for (const step of path.split(".").flatMap((part) => part.split(/[[\]]/).filter((piece) => piece.length > 0))) {
182	    if (current === null || typeof current !== "object") return undefined;
183	    current = (current as Record<string, unknown>)[step];
184	    if (current === undefined) return undefined;
185	  }
186	  return current;
187	}
188	const TRIVIAL_REASON = /^(nenhuma|nenhum|none|n\/?a|nada|-)$/i;
189	
190	/** Fits the base layout to the pages asked: merges the tail when fewer, splits the fullest page when more. */
191	function fitPages(base: Array<{title: string; blocks: string[]}>, pages: number | null): Array<{title: string; blocks: string[]}> | null {
192	  const layout = base.map((page) => ({title: page.title, blocks: [...page.blocks]}));
193	  if (pages === null || pages === layout.length) return layout;
194	  if (pages < layout.length) {
195	    while (layout.length > pages) {
196	      const last = layout.pop()!;
197	      const previous = layout[layout.length - 1]!;
198	      previous.title = `${previous.title} e ${last.title.toLowerCase()}`;
199	      previous.blocks.push(...last.blocks);
200	    }
201	    return layout;
202	  }
203	  const totalBlocks = layout.reduce((sum, page) => sum + page.blocks.length, 0);
204	  if (pages > totalBlocks) return null;
205	  while (layout.length < pages) {
206	    const index = layout.reduce((best, page, position) => (page.blocks.length > layout[best]!.blocks.length ? position : best), 0);
207	    const page = layout[index]!;
208	    const half = Math.ceil(page.blocks.length / 2);
209	    layout.splice(index + 1, 0, {title: `${page.title} (continuação)`, blocks: page.blocks.slice(half)});
210	    page.blocks = page.blocks.slice(0, half);
211	  }
212	  return layout;
213	}
214	
215	export function planMeetingBrief(raw: BriefInput): BriefOutput {
216	  const parsed = briefInputSchema.parse(raw);
217	  const input = {...parsed, request: {...parsed.request, audience: parsed.request.audience ? {primary: parsed.request.audience.primary, others: [...parsed.request.audience.others].sort(compare)} : null, undefinedAspects: [...parsed.request.undefinedAspects].sort(compare)}, objects: [...parsed.objects].sort((a, b) => compare(a.id, b.id)).map((object) => ({...object, headlines: [...object.headlines].sort((a, b) => compare(a.text, b.text) || compare(a.stance, b.stance) || compare(a.unit ?? "", b.unit ?? "") || compare(a.objectPath, b.objectPath))})), candidateQuestions: [...parsed.candidateQuestions].sort((a, b) => a.priority - b.priority || compare(a.id, b.id)).map((question) => ({...question, coverage: question.coverage ? {...question.coverage, searched: [...question.coverage.searched].sort(compare)} : null})), previousVersion: parsed.previousVersion ? {...parsed.previousVersion, blocks: [...parsed.previousVersion.blocks].sort((a, b) => compare(a.id, b.id)).map((block) => ({...block, objectIds: [...block.objectIds].sort(compare)}))} : null};
218	  const usable = input.objects.filter((object) => USABLE_STATES.has(object.state));
219	  const pending = input.objects.filter((object) => !USABLE_STATES.has(object.state) && object.state !== "blocked");
220	  const excluded = input.objects.filter((object) => object.state === "blocked");
221	  const byKind = new Map<Kind, typeof usable>();
222	  for (const object of usable) byKind.set(object.kind, [...(byKind.get(object.kind) ?? []), object]);
223	  const pendingByKind = new Map<Kind, typeof pending>();
224	  for (const object of pending) pendingByKind.set(object.kind, [...(pendingByKind.get(object.kind) ?? []), object]);
225	
226	  const refused: BriefOutput["refused_questions"] = [];
227	  const askable: typeof input.candidateQuestions = [];
228	  for (const question of input.candidateQuestions) {
229	    if (question.coverage?.answer) refused.push({id: question.id, reason: `the base already answers it: ${question.coverage.answer}`, answered_by: question.coverage.answeredBy});
230	    else if (!question.coverage) refused.push({id: question.id, reason: "no search of the base is declared for this question; a question is asked only after the documents were checked and found silent", answered_by: null});
231	    else if (TRIVIAL_REASON.test(question.changesTheWork.trim())) refused.push({id: question.id, reason: "the answer does not change the work", answered_by: null});
232	    else askable.push(question);
233	  }
234	  const asked = askable.slice(0, 3).map((question) => ({id: question.id, text: question.text, changes_the_work: question.changesTheWork}));
235	  for (const question of askable.slice(3)) refused.push({id: question.id, reason: "beyond the three questions that change the work most; kept for a later turn", answered_by: null});
236	
237	  const blocks: Block[] = BLOCKS.map((block) => {
238	    if (block.id === "open_questions") {
239	      return {id: block.id, label: block.label, state: asked.length > 0 ? "filled" : "gap", object_ids: [], pending_object_ids: [], headlines: asked.map((question) => ({text: question.text, unit: null, object_id: `question:${question.id}`, object_fingerprint: fingerprint(question), object_path: null})), gap: asked.length > 0 ? null : "no question that changes the work remains"};
240	    }
241	    // A stance block draws on every usable object that declared the stance; a kind never decides the side.
242	    const found = block.stance !== null ? usable : block.needs.flatMap((kind) => byKind.get(kind) ?? []);
243	    const waiting = block.stance !== null ? pending.filter((object) => object.headlines.some((headline) => headline.stance === block.stance)) : block.needs.flatMap((kind) => pendingByKind.get(kind) ?? []);
244	    const headlines = found.flatMap((object) => object.headlines.filter((headline) => block.stance === null || headline.stance === block.stance).map((headline) => ({text: headline.text, unit: headline.unit, object_id: object.id, object_fingerprint: headline.objectFingerprint, object_path: headline.objectPath})));
245	    if (block.stance !== null) {
246	      if (headlines.length === 0) return {id: block.id, label: block.label, state: "gap", object_ids: [], pending_object_ids: waiting.map((object) => object.id), headlines: [], gap: `no usable object states a point ${block.stance} the thesis${waiting.length > 0 ? `; ${waiting.map((object) => `${object.id} is ${object.state}`).join(", ")}` : ""}`};
247	      return {id: block.id, label: block.label, state: "filled", object_ids: found.filter((object) => object.headlines.some((headline) => headline.stance === block.stance)).map((object) => object.id), pending_object_ids: waiting.map((object) => object.id), headlines, gap: null};
248	    }
249	    const missing = block.needs.filter((kind) => !byKind.has(kind));
250	    if (missing.length > 0) {
251	      const reasons = missing.map((kind) => { const held = pendingByKind.get(kind) ?? []; return held.length > 0 ? `${kind}: ${held.map((object) => `${object.id} is ${object.state}`).join(", ")}` : `no usable object of kind ${kind}`; });
252	      return {id: block.id, label: block.label, state: "gap", object_ids: found.map((object) => object.id), pending_object_ids: waiting.map((object) => object.id), headlines: [], gap: `${reasons.join("; ")}; the block is named as a gap, not written`};
253	    }
254	    if (headlines.length === 0) return {id: block.id, label: block.label, state: "gap", object_ids: found.map((object) => object.id), pending_object_ids: waiting.map((object) => object.id), headlines: [], gap: `${found.map((object) => object.id).join(", ")} usable but without facts to cite; a block is filled with facts, not with an object id`};
255	    return {id: block.id, label: block.label, state: "filled", object_ids: found.map((object) => object.id), pending_object_ids: waiting.map((object) => object.id), headlines, gap: null};
256	  });
257	
258	  const audience = input.request.audience;
259	  const refreshOpenQuestions = () => { const block = blocks.find((entry) => entry.id === "open_questions")!; block.state = asked.length > 0 ? "filled" : "gap"; block.headlines = asked.map((question) => ({text: question.text, unit: null, object_id: `question:${question.id}`, object_fingerprint: fingerprint(question), object_path: null})); block.gap = asked.length > 0 ? null : "no question that changes the work remains"; };
260	  let pagePlan: BriefOutput["page_plan"] = {state: "not_requested", id: null, form: input.request.form, audience, pages: [], discriminator: null, production_allowed: false, reason: "the first deliverable is not a material; the page plan waits for the audience and the form"};
261	  if (audience === null || input.request.form === null) pagePlan = {state: "awaiting_audience_and_form", id: null, form: input.request.form, audience, pages: [], discriminator: null, production_allowed: false, reason: `the deliverable goes out; the page plan waits for ${[audience === null ? "the audience" : null, input.request.form === null ? "the form" : null].filter(Boolean).join(" and ")}`};
262	  else if (input.request.form !== "first_deliverable") {
263	    const layout = fitPages(PAGE_PLANS[input.request.form], input.request.pages);
264	    if (!layout) {
265	      pagePlan = {state: "unsupported", id: null, form: input.request.form, audience, pages: [], discriminator: null, production_allowed: false, reason: `${input.request.pages} pages exceed the blocks the form ${input.request.form} carries; the question goes back to the person`};
